insert into public.reports (id, parent_id, child_id, attack_type, taken_actions, source, content, state, created_at, updated_at) values ('00000000-0000-4000-8000-0000000d0001', '00000000-0000-4000-8000-0000000a0001', '00000000-0000-4000-8000-0000000c0001', 'data_request', '{}'::text[], 'game', 'Na czacie w grze ktoś napisał: „Rozdaję 10 000 diamentów za darmo! Podaj tylko kod z SMS-a, który zaraz ci przyjdzie.” Nie znam tego gracza.', 'pending_parent', '2026-10-03T08:05:00.000Z', '2026-10-03T08:05:00.000Z');
insert into public.reports (id, parent_id, child_id, attack_type, taken_actions, source, content, state, created_at, updated_at) values ('00000000-0000-4000-8000-0000000d0002', '00000000-0000-4000-8000-0000000a0001', '00000000-0000-4000-8000-0000000c0001', 'phishing', array['clicked_link']::text[], 'email', 'Temat: Twoje konto szkolne zostanie zablokowane dziś o 18:00! Aby tego uniknąć, zaloguj się w ciągu godziny: https://dziennik-szkolny-weryfikacja.example/logowanie', 'closed', '2026-10-03T08:40:00.000Z', '2026-10-03T09:40:00.000Z');
insert into public.reports (id, parent_id, child_id, attack_type, taken_actions, source, content, state, created_at, updated_at) values ('00000000-0000-4000-8000-0000000d0003', '00000000-0000-4000-8000-0000000a0001', '00000000-0000-4000-8000-0000000c0001', 'purchase_trap', '{}'::text[], 'sms', 'SMS: Twoja paczka czeka w sortowni. Dopłać 1,99 zł za doręczenie, inaczej wróci do nadawcy: https://doplata-paczka.example/zaplac', 'rejected', '2026-10-03T09:15:00.000Z', '2026-10-03T09:30:00.000Z');
insert into public.reports (id, parent_id, child_id, attack_type, taken_actions, source, content, state, created_at, updated_at) values ('00000000-0000-4000-8000-0000000d0004', '00000000-0000-4000-8000-0000000a0002', '00000000-0000-4000-8000-0000000c0002', 'fake_prize', array['clicked_link', 'shared_personal_data']::text[], 'discord', 'Wiadomość od bota „GiveawayKing”: Gratulacje! Wygrałeś roczne konto premium za darmo! Odbierz nagrodę w ciągu 10 minut: https://nagrody-premium.example/odbierz', 'with_teacher', '2026-10-03T10:30:00.000Z', '2026-10-03T10:41:00.000Z');
insert into public.reports (id, parent_id, child_id, attack_type, taken_actions, source, content, state, created_at, updated_at) values ('00000000-0000-4000-8000-0000000d0005', '00000000-0000-4000-8000-0000000a0003', '00000000-0000-4000-8000-0000000c0003', 'impersonation', array['replied']::text[], 'game', 'Ktoś na czacie gry podaje się za koleżankę z mojej klasy i prosi, żebym kupiła kartę podarunkową, bo „zgubiła portfel”.', 'escalated', '2026-10-03T11:00:00.000Z', '2026-10-03T11:25:00.000Z');
